  // src/game/action/enemy/scale.ts
  var K2 = PIXEL / 2;
  var seenBox = /* @__PURE__ */ new WeakSet();
  var seenMove = /* @__PURE__ */ new WeakSet();
  function box(b) {
    if (seenBox.has(b)) return;
    seenBox.add(b);
    b.fx0 *= K2;
    b.fx1 *= K2;
    b.z0 *= K2;
    b.z1 *= K2;
  }
  function move(m) {
    if (seenMove.has(m)) return;
    seenMove.add(m);
    for (const f of m.frames) {
      f.hit.forEach(box);
      f.hurt.forEach(box);
      if (f.vx) f.vx *= K2;
      if (f.vz) f.vz *= K2;
    }
    for (const d3 of m.danger ?? []) if (!seenBox.has(d3)) seenBox.add(d3), d3.fx0 *= K2, d3.fx1 *= K2;
  }
  var done = false;
  function scaleAll(defs) {
    if (done || K2 === 1) return;
    done = true;
    for (const d3 of defs) {
      d3.w *= K2;
      d3.h *= K2;
      d3.speed *= K2;
      if (d3.hover) d3.hover *= K2;
      d3.keep = [d3.keep[0] * K2, d3.keep[1] * K2];
      d3.body.forEach(box);
      for (const a of d3.attacks) {
        move(a.move);
        a.range = [a.range[0] * K2, a.range[1] * K2];
      }
    }
    for (const p of Object.values(PROJ)) {
      p.w *= K2;
      p.h *= K2;
      p.z *= K2;
      p.speed *= K2;
      if (p.vz) p.vz *= K2;
      if (p.gravity) p.gravity *= K2;
      if (p.grow) p.grow *= K2;
    }
  }

