        ctx.save();
        ctx.font = pfont(54).f;
        ctx.textAlign = "right";
        ctx.fillStyle = "#ffd36a";
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 6;
        ctx.strokeText(`${p.combo} HIT`, SCREEN_W - 30, 80);
