  function syncNavigationButton(canvas, navigation) {
    const button = canvas.closest(".gs")?.querySelector('.tp [data-id="interact"]');
    if (!button) return;
    const target = navigation?.target;
    const locked = target?.kind === "locked";
    const active = !!target && !locked && target.kind !== "decoration";
    const text2 = locked ? "잠김" : "조사";
    const description = target ? `${text2} · ${target.text}${target.reason ? ` · ${target.reason}` : ""}` : "조사 · 표시된 대상에 가까이 가세요";
    if (button.getAttribute("aria-label") === description) return;
    button.setAttribute("aria-label", description);
    button.title = description;
    button.classList.toggle("hint", active);
    const label3 = button.querySelector("b");
    if (!label3) return;
    label3.textContent = text2;
    Object.assign(label3.style, {
      display: "block",
      position: "absolute",
      inset: "auto 2px 2px",
      background: "rgba(7,11,15,.9)",
      color: locked ? "#f0b45a" : "#fff8e6",
      font: "700 12px sans-serif",
      lineHeight: "15px",
      textAlign: "center",
      pointerEvents: "none",
      textShadow: "none"
    });
  }

